// Derives inspector form fields from a node's config JSON Schema (generated by Pydantic).

import type { JsonSchema } from "../api/types";

export type FieldKind = "artifacts" | "routes" | "route_ref" | "secret" | "enum" | "boolean" | "integer" | "number" | "string" | "textarea" | "json";

export interface FieldSpec {
  name: string;
  title: string;
  description?: string;
  kind: FieldKind;
  options?: (string | number)[];
  default?: unknown;
  minimum?: number;
  maximum?: number;
  advanced: boolean;
  placeholder?: string;
  required: boolean;
}

function deref(root: JsonSchema, schema: JsonSchema): JsonSchema {
  if (schema.$ref) {
    const name = schema.$ref.split("/").pop() ?? "";
    const target = root.$defs?.[name] ?? {};
    // property-level keywords (default, description, x-ui...) override the referenced schema
    const { $ref: _ignored, ...rest } = schema;
    void _ignored;
    return { ...target, ...rest };
  }
  return schema;
}

function humanize(name: string): string {
  return name.replace(/_/g, " ").replace(/^\w/, (c) => c.toUpperCase());
}

export function fieldsFromSchema(root: JsonSchema): FieldSpec[] {
  const required = new Set(root.required ?? []);
  return Object.entries(root.properties ?? {}).map(([name, raw]) => {
    let prop = deref(root, raw);
    if (prop.anyOf) {
      const nonNull = prop.anyOf.map((s) => deref(root, s)).find((s) => s.type !== "null");
      prop = { ...(nonNull ?? {}), ...prop, anyOf: undefined };
    }
    const ui = prop["x-ui"] ?? {};
    let kind: FieldKind;
    let options: (string | number)[] | undefined;
    if (ui.widget === "artifacts") kind = "artifacts";
    else if (ui.widget === "model_routes") kind = "routes";
    else if (ui.widget === "route_ref") kind = "route_ref";
    else if (raw["x-secret"] || prop["x-secret"]) kind = "secret";
    else if (prop.enum) {
      kind = "enum";
      options = prop.enum;
    } else if (prop.const !== undefined) {
      kind = "enum";
      options = [prop.const];
    } else if (prop.type === "boolean") kind = "boolean";
    else if (prop.type === "integer") kind = "integer";
    else if (prop.type === "number") kind = "number";
    else if (prop.type === "string") kind = ui.widget === "textarea" ? "textarea" : "string";
    else kind = "json";
    return {
      name,
      // a referenced type's own title (e.g. "SecretRef") names the type, not this field
      title: raw.title ?? (raw.$ref || raw.anyOf ? humanize(name) : (prop.title ?? humanize(name))),
      description: raw.description ?? prop.description,
      kind,
      options,
      default: raw.default !== undefined ? raw.default : prop.default,
      minimum: prop.minimum,
      maximum: prop.maximum,
      advanced: Boolean(ui.advanced),
      placeholder: ui.placeholder,
      required: required.has(name),
    };
  });
}
